insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'edgegod', 'EdgeGod', array['tool','tipster']::listing_type[], 'Cricket analytics for traders: match previews, venue data and par-score models.', 'A cricket analytics desk covering the IPL, Tests, ODIs and franchise leagues. Format-aware match previews, venue analytics, session par-score models and a public ledger tracking results in units. A higher tier adds a private Telegram channel.', 'https://edgegod.in', 'paid'::pricing_model, 'INR 2,500 a month for the website, or 5,000 with the private Telegram channel', array['cricket']::text[], 'Stats and data', array['Web app','Telegram channel','Projections','Matchup data','Publicly tracked record','Paid picks']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Small account (about 750 followers). The unit results on the site and in the bio are his own figures; do not repeat them. Sales run through WhatsApp and Telegram, so check what is promoted there, including any betting exchanges or ID services. Prices were read from the site on 27 November 2026.", "country": "IN", "categories": ["Stats and data", "Models and projections"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('EdgeGod')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://edgegod.in'),('X','https://x.com/EdgeGodX'),('Telegram','https://t.me/TheEdgeGod')) as v(platform,url) where l.slug = 'edgegod' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'ed-hawkins', 'Ed Hawkins', array['tipster','creator']::listing_type[], 'Award-winning cricket writer and long-time cricket betting tipster.', 'Ed Hawkins is a London-based author and cricket betting writer who has covered the game''s markets for well over a decade. He posts tips and previews for Tests and T20 leagues on X, with a Telegram tips channel.', 'https://x.com/cricketbetting', 'free'::pricing_model, null, array['cricket']::text[], null, array['Free picks','Write-ups with reasoning','Telegram channel']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "DECISION NEEDED: he writes cricket tips for Betfair and most posts link to Betfair''s betting site. That is bookmaker content, which cuts against your no-bookmaker stance. Well established (12.5K followers, on X since 2009), so quality is not the issue. Check whether the Telegram channel is free or paid.", "country": "GB"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Ed Hawkins')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('X','https://x.com/cricketbetting'),('Telegram','https://telegram.cricstatz.ai')) as v(platform,url) where l.slug = 'ed-hawkins' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
